pub struct FontContextCursor{face:FontFace,lookup:FontLookup,glyph_pointer:usize,glyph_count:usize,font_pointer:Option<usize>,start:usize,max_work:u64,phase:u8,sub:usize,table:usize,format:u16,probe:Option<Index>,coverage:usize,set:usize,set_at:usize,rules:usize,offsets:[usize;3],counts:[usize;3],class_defs:[usize;3],input_count:usize,record_offset:usize,record_count:usize,section:usize,index:usize,record_at:usize,output:Option<FontContextMatch>,work:u64,cancelled:bool,failure:Option<String>}
impl RetireOwned for FontContextCursor{fn retirement(self)->Box<dyn RetirementCursor>{self.failure.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.failure.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
impl FontContextCursor{
 pub fn new(face:FontFace,lookup:FontLookup,glyphs:&[u16],start:usize,max_work:u64)->Self{let invalid=face.gsub.is_none()||!matches!(lookup.kind,5|6)||!matches!(lookup.flags,0|8)||start>=glyphs.len()||!(1..=1000000000).contains(&max_work);Self{face,lookup,glyph_pointer:glyphs.as_ptr()as usize,glyph_count:glyphs.len(),font_pointer:None,start,max_work,phase:0,sub:0,table:0,format:0,probe:None,coverage:0,set:0,set_at:0,rules:0,offsets:[0;3],counts:[0;3],class_defs:[0;3],input_count:0,record_offset:0,record_count:0,section:0,index:0,record_at:0,output:None,work:0,cancelled:false,failure:invalid.then(||"Invalid original contextual lookup authority".into())}}
 fn miss(&mut self){self.probe=None;if self.format==3{self.sub+=1;self.phase=0;}else{self.phase=4;}}
 fn sections(&mut self,r:FontReader<'_>,at:usize,coverage:bool)->Result<(),String>{let chain=self.lookup.kind==6;let mut p=at;self.counts=[0;3];self.offsets=[0;3];if chain{self.counts[0]=usize::from(r.u16(p)?);self.offsets[0]=p+2;p+=2+self.counts[0]*2;}self.input_count=usize::from(r.u16(p)?);if !(1..=128).contains(&self.input_count){return Err("Font contextual input limit exceeded".into());}if !chain{self.record_count=usize::from(r.u16(p+2)?);p+=4;}else{p+=2;}self.counts[1]=self.input_count-usize::from(!coverage);self.offsets[1]=p;p+=self.counts[1]*2;if chain{self.counts[2]=usize::from(r.u16(p)?);self.offsets[2]=p+2;p+=2+self.counts[2]*2;self.record_count=usize::from(r.u16(p)?);p+=2;}if self.counts.into_iter().any(|count|count>128)||self.record_count>128{return Err("Font contextual record limit exceeded".into());}r.range(at,p-at+self.record_count*4)?;self.record_offset=p;self.section=0;self.index=0;if self.counts[0]>self.start||self.start+self.input_count+self.counts[2]>self.glyph_count{self.miss();}else{self.phase=5;}Ok(())}
 fn step(&mut self,bytes:&[u8],glyphs:&[u16])->Result<(),String>{if bytes.len()!=self.face.byte_length||self.font_pointer.is_some_and(|pointer|pointer!=bytes.as_ptr()as usize)||glyphs.as_ptr()as usize!=self.glyph_pointer||glyphs.len()!=self.glyph_count{return Err("Original contextual sources changed".into());}self.font_pointer=Some(bytes.as_ptr()as usize);let r=FontReader::new(bytes,self.face.gsub.ok_or("Original context table missing")?)?;match self.phase{
  0=>{if self.sub==self.lookup.subtables{self.phase=7;return Ok(());}self.table=self.lookup.offset+usize::from(r.u16(self.lookup.offset+6+self.sub*2)?);self.format=r.u16(self.table)?;if !matches!(self.format,1|2|3){return Err("Unsupported original contextual format".into());}if self.format==3{if self.lookup.kind==5{self.input_count=usize::from(r.u16(self.table+2)?);self.record_count=usize::from(r.u16(self.table+4)?);if !(1..=128).contains(&self.input_count)||self.record_count>128{return Err("Font contextual record limit exceeded".into());}self.counts=[0,self.input_count,0];self.offsets=[0,self.table+6,0];self.record_offset=self.table+6+self.input_count*2;r.range(self.table+6,self.input_count*2+self.record_count*4)?;self.section=0;self.index=0;if self.start+self.input_count>glyphs.len(){self.miss();}else{self.phase=5;}}else{self.sections(r,self.table+2,true)?;}return Ok(());}self.probe=Some(Index::new(r,self.table+usize::from(r.u16(self.table+2)?),glyphs[self.start],false)?);self.phase=1;},
  1=>{if !self.probe.as_mut().unwrap().step(r)?{return Ok(());}let coverage=self.probe.as_ref().unwrap().result();self.probe=None;if coverage<0{self.sub+=1;self.phase=0;return Ok(());}self.coverage=coverage as usize;if self.format==2{let fields=if self.lookup.kind==6{3}else{1};for at in 0..fields{let offset=usize::from(r.u16(self.table+4+at*2)?);self.class_defs[if self.lookup.kind==6{at}else{1}]=if offset==0{0}else{self.table+offset};}if self.class_defs[1]!=0{self.probe=Some(Index::new(r,self.class_defs[1],glyphs[self.start],true)?);self.phase=2;return Ok(());}self.coverage=0;}self.phase=3;},
  2=>{if self.probe.as_mut().unwrap().step(r)?{self.coverage=self.probe.as_ref().unwrap().result()as usize;self.probe=None;self.phase=3;}},
  3=>{let header=if self.format==1{4}else if self.lookup.kind==6{10}else{6};let count=usize::from(r.u16(self.table+header)?);if self.coverage>=count{self.sub+=1;self.phase=0;return Ok(());}let offset=usize::from(r.u16(self.table+header+2+self.coverage*2)?);if offset==0{self.sub+=1;self.phase=0;return Ok(());}self.set=self.table+offset;self.rules=usize::from(r.u16(self.set)?);r.range(self.set+2,self.rules*2)?;self.set_at=0;self.phase=4;},
  4=>{if self.set_at==self.rules{self.sub+=1;self.phase=0;return Ok(());}let rule=self.set+usize::from(r.u16(self.set+2+self.set_at*2)?);self.set_at+=1;self.sections(r,rule,false)?;},
  5=>{if self.section==3{self.output=Some(FontContextMatch{input_count:self.input_count,records:[FontSequenceLookup::default();128],count:0});self.record_at=0;self.phase=6;return Ok(());}if self.index==self.counts[self.section]{self.section+=1;self.index=0;return Ok(());}let position=match self.section{0=>self.start-self.index-1,1=>self.start+self.index+usize::from(self.format!=3),_=>self.start+self.input_count+self.index};let glyph=glyphs[position];let expected=r.u16(self.offsets[self.section]+self.index*2)?;if self.format==1{if glyph!=expected{self.miss();}else{self.index+=1;}return Ok(());}if self.probe.is_none(){let at=if self.format==3{self.table+usize::from(expected)}else{self.class_defs[self.section]};if at==0{if expected!=0{self.miss();}else{self.index+=1;}return Ok(());}self.probe=Some(Index::new(r,at,glyph,self.format==2)?);return Ok(());}if self.probe.as_mut().unwrap().step(r)?{let value=self.probe.as_ref().unwrap().result();self.probe=None;if if self.format==3{value<0}else{value!=i32::from(expected)}{self.miss();}else{self.index+=1;}}},
  6=>{if self.record_at==self.record_count{self.phase=7;return Ok(());}let at=self.record_offset+self.record_at*4;let sequence=usize::from(r.u16(at)?);let lookup=r.u16(at+2)?;let table=self.face.gsub.unwrap();let list=table.offset+usize::from(r.u16(table.offset+8)?);if sequence>=self.input_count||lookup>=r.u16(list)?{return Err("Font contextual lookup record exceeds authority".into());}self.output.as_mut().unwrap().records[self.record_at]=FontSequenceLookup{sequence,lookup};self.record_at+=1;self.output.as_mut().unwrap().count=self.record_at;},
  _=>return Err("Original contextual stage invalid".into()),
 }Ok(())}
 pub fn advance(&mut self,bytes:&[u8],glyphs:&[u16],grant:usize)->Result<FontProgress,String>{if grant==0{return Err("Invalid contextual work grant".into());}if self.cancelled{return Err("Original contextual lookup cancelled".into());}if let Some(error)=&self.failure{return Err(error.clone());}for _ in 0..grant{if self.phase==7{break;}if self.work==self.max_work{self.failure=Some("Font contextual work limit exceeded".into());return Err(self.failure.as_ref().unwrap().clone());}if let Err(error)=self.step(bytes,glyphs){self.failure=Some(error.clone());return Err(error);}self.work+=1;}Ok(FontProgress{phase:match self.phase{0=>"subtable",1=>"coverage",2=>"class",3=>"set",4=>"rule",5=>"match",6=>"records",_=>"complete"},work:self.work,done:self.phase==7})}
 pub fn result(&self)->Result<Option<FontContextMatch>,String>{if self.phase!=7||self.cancelled||self.failure.is_some(){return Err("Original contextual lookup incomplete".into());}Ok(self.output)}
 pub fn cancel(&mut self){self.cancelled=true;}
}
